import{_ as e,o as d,c as o,ag as a}from"./chunks/framework.C2NLiVii.js";const m=JSON.parse('{"title":"Command-Line Tools","description":"","frontmatter":{},"headers":[],"relativePath":"tools.md","filePath":"tools.md"}'),s={name:"tools.md"};function i(r,t,n,c,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="command-line-tools" tabindex="-1">Command-Line Tools <a class="header-anchor" href="#command-line-tools" aria-label="Permalink to &quot;Command-Line Tools&quot;">​</a></h1><p>OSRM ships six command-line tools that cover the full data pipeline, from raw OSM data to a running routing server. All tools share a set of common options described below, followed by per-tool reference sections.</p><h2 id="common-options" tabindex="-1">Common Options <a class="header-anchor" href="#common-options" aria-label="Permalink to &quot;Common Options&quot;">​</a></h2><p>These flags are accepted by every tool.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Short</th><th>Description</th></tr></thead><tbody><tr><td><code>--help</code></td><td><code>-h</code></td><td>Show the help message and exit.</td></tr><tr><td><code>--version</code></td><td><code>-v</code></td><td>Show the version string and exit.</td></tr><tr><td><code>--verbosity &lt;level&gt;</code></td><td><code>-l</code></td><td>Log verbosity: <code>NONE</code>, <code>ERROR</code>, <code>WARNING</code>, <code>INFO</code> (default), <code>DEBUG</code>.</td></tr><tr><td><code>--list-inputs</code></td><td></td><td>Print all required and optional input file extensions the tool expects, then exit. Useful for deployment scripts.</td></tr><tr><td><code>--threads &lt;n&gt;</code></td><td><code>-t</code></td><td>Number of threads to use (default: number of logical CPUs).</td></tr></tbody></table><h3 id="list-inputs" tabindex="-1"><code>--list-inputs</code> <a class="header-anchor" href="#list-inputs" aria-label="Permalink to &quot;\`--list-inputs\`&quot;">​</a></h3><p>Prints one line per file in the format <code>required|optional &lt;extension&gt;</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ osrm-routed --list-inputs</span></span>
<span class="line"><span>required .osrm.datasource_names</span></span>
<span class="line"><span>required .osrm.ebg_nodes</span></span>
<span class="line"><span>required .osrm.edges</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>optional .osrm.hsgr</span></span>
<span class="line"><span>optional .osrm.cells</span></span></code></pre></div><p>Example — collect all files needed to deploy <code>osrm-routed</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">map</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> line </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">osrm-routed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list-inputs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE$line</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">done</span></span></code></pre></div><hr><h2 id="osrm-extract" tabindex="-1">osrm-extract <a class="header-anchor" href="#osrm-extract" aria-label="Permalink to &quot;osrm-extract&quot;">​</a></h2><p>Reads an OSM file and a Lua profile, and produces the intermediate <code>.osrm.*</code> files consumed by the graph-preparation tools.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>osrm-extract &lt;input.osm/.osm.bz2/.osm.pbf&gt; [options]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Short</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>--profile &lt;path&gt;</code></td><td><code>-p</code></td><td><code>profiles/car.lua</code></td><td>Path to the Lua routing profile.</td></tr><tr><td><code>--output &lt;path&gt;</code></td><td><code>-o</code></td><td>Derived from input filename</td><td>Base path for generated output files.</td></tr><tr><td><code>--data_version &lt;string&gt;</code></td><td><code>-d</code></td><td><em>(none)</em></td><td>Tag the dataset with a version string. Use <code>osmosis</code> to read the timestamp embedded in the PBF file.</td></tr><tr><td><code>--small-component-size &lt;n&gt;</code></td><td></td><td><code>1000</code></td><td>Minimum node count for a strongly-connected component to be treated as &quot;large&quot;. Affects nearest-neighbor snapping.</td></tr><tr><td><code>--with-osm-metadata</code></td><td></td><td></td><td>Parse OSM metadata (user, timestamp, etc.). May reduce extraction performance.</td></tr><tr><td><code>--parse-conditional-restrictions</code></td><td></td><td></td><td>Save conditional turn restrictions to disk so they can be evaluated during contraction.</td></tr><tr><td><code>--location-dependent-data &lt;file&gt;</code></td><td></td><td></td><td>GeoJSON files containing location-dependent data (e.g. speed limits by region). Repeatable.</td></tr><tr><td><code>--disable-location-cache</code></td><td></td><td></td><td>Disable the internal node-location cache used for location-dependent data lookups.</td></tr><tr><td><code>--dump-nbg-graph</code></td><td></td><td></td><td>Write the raw node-based graph to the <code>.osrm</code> file for debugging.</td></tr></tbody></table><hr><h2 id="osrm-partition" tabindex="-1">osrm-partition <a class="header-anchor" href="#osrm-partition" aria-label="Permalink to &quot;osrm-partition&quot;">​</a></h2><p>Partitions the road network graph into a hierarchy of cells used by the Multi-Level Dijkstra (MLD) algorithm.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>osrm-partition &lt;input.osrm&gt; [options]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>--max-cell-sizes &lt;list&gt;</code></td><td><code>128,4096,65536,2097152</code></td><td>Comma-separated maximum cell sizes per level, starting from level 1. The first value is also the bisection termination threshold.</td></tr><tr><td><code>--balance &lt;factor&gt;</code></td><td><code>1.2</code></td><td>Maximum allowed size ratio between the two sides of a single bisection.</td></tr><tr><td><code>--boundary &lt;fraction&gt;</code></td><td><code>0.25</code></td><td>Fraction of nodes to use as boundary sources/sinks during contraction.</td></tr><tr><td><code>--optimizing-cuts &lt;n&gt;</code></td><td><code>10</code></td><td>Number of candidate cuts evaluated when optimizing a single bisection.</td></tr><tr><td><code>--small-component-size &lt;n&gt;</code></td><td><code>1000</code></td><td>Node-count threshold below which a component is treated as small.</td></tr></tbody></table><hr><h2 id="osrm-customize" tabindex="-1">osrm-customize <a class="header-anchor" href="#osrm-customize" aria-label="Permalink to &quot;osrm-customize&quot;">​</a></h2><p>Applies live traffic data (speed and turn-penalty files) to a partitioned MLD graph. Can be run repeatedly without re-partitioning when speeds change.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>osrm-customize &lt;input.osrm&gt; [options]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>--segment-speed-file &lt;file&gt;</code></td><td></td><td>CSV with <code>nodeA,nodeB,speed</code> columns to override edge weights. Repeatable.</td></tr><tr><td><code>--turn-penalty-file &lt;file&gt;</code></td><td></td><td>CSV with <code>from_node,via_node,to_node,penalty</code> to override turn weights. Repeatable.</td></tr><tr><td><code>--edge-weight-updates-over-factor &lt;x&gt;</code></td><td><code>0</code> (disabled)</td><td>Log edges whose weight changed by more than factor <code>x</code> (requires <code>--segment-speed-file</code>).</td></tr><tr><td><code>--parse-conditionals-from-now &lt;utc_timestamp&gt;</code></td><td><code>0</code> (disabled)</td><td>UTC Unix timestamp from which to evaluate conditional turn restrictions.</td></tr><tr><td><code>--time-zone-file &lt;file&gt;</code></td><td></td><td>GeoJSON file with time-zone boundaries, required for conditional restriction parsing.</td></tr></tbody></table><hr><h2 id="osrm-contract" tabindex="-1">osrm-contract <a class="header-anchor" href="#osrm-contract" aria-label="Permalink to &quot;osrm-contract&quot;">​</a></h2><p>Builds a Contraction Hierarchy (CH) from the extracted graph. Use this instead of <code>osrm-partition</code> + <code>osrm-customize</code> when you don&#39;t need live traffic updates.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>osrm-contract &lt;input.osrm&gt; [options]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>--segment-speed-file &lt;file&gt;</code></td><td></td><td>CSV with <code>nodeA,nodeB,speed</code> columns to override edge weights. Repeatable.</td></tr><tr><td><code>--turn-penalty-file &lt;file&gt;</code></td><td></td><td>CSV with <code>from_node,via_node,to_node,penalty</code> to override turn weights. Repeatable.</td></tr><tr><td><code>--edge-weight-updates-over-factor &lt;x&gt;</code></td><td><code>0</code> (disabled)</td><td>Log edges whose weight changed by more than factor <code>x</code>.</td></tr><tr><td><code>--parse-conditionals-from-now &lt;utc_timestamp&gt;</code></td><td><code>0</code> (disabled)</td><td>UTC Unix timestamp for evaluating conditional turn restrictions.</td></tr><tr><td><code>--time-zone-file &lt;file&gt;</code></td><td></td><td>GeoJSON file with time-zone boundaries, required for conditional restriction parsing.</td></tr></tbody></table><hr><h2 id="osrm-routed" tabindex="-1">osrm-routed <a class="header-anchor" href="#osrm-routed" aria-label="Permalink to &quot;osrm-routed&quot;">​</a></h2><p>The HTTP server. Loads a prepared dataset and serves the OSRM HTTP API.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>osrm-routed &lt;base.osrm&gt; [options]</span></span></code></pre></div><h3 id="server" tabindex="-1">Server <a class="header-anchor" href="#server" aria-label="Permalink to &quot;Server&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Short</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>--ip &lt;address&gt;</code></td><td><code>-i</code></td><td><code>0.0.0.0</code></td><td>IP address to listen on.</td></tr><tr><td><code>--port &lt;n&gt;</code></td><td><code>-p</code></td><td><code>5000</code></td><td>TCP port to listen on.</td></tr><tr><td><code>--keepalive-timeout &lt;s&gt;</code></td><td><code>-k</code></td><td><code>5</code></td><td>HTTP keep-alive timeout in seconds.</td></tr><tr><td><code>--trial</code></td><td></td><td></td><td>Start up fully, then exit immediately. Useful to validate a dataset without serving traffic.</td></tr></tbody></table><h3 id="data-loading" tabindex="-1">Data loading <a class="header-anchor" href="#data-loading" aria-label="Permalink to &quot;Data loading&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Short</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>--algorithm &lt;name&gt;</code></td><td><code>-a</code></td><td><code>CH</code></td><td>Routing algorithm: <code>CH</code> (Contraction Hierarchy) or <code>MLD</code> (Multi-Level Dijkstra).</td></tr><tr><td><code>--shared-memory</code></td><td><code>-s</code></td><td>off</td><td>Load data from a shared memory region managed by <code>osrm-datastore</code>.</td></tr><tr><td><code>--mmap</code></td><td><code>-m</code></td><td>off</td><td>Memory-map the data files instead of loading them into RAM.</td></tr><tr><td><code>--dataset-name &lt;name&gt;</code></td><td></td><td></td><td>Shared memory dataset name to connect to (used with <code>--shared-memory</code>).</td></tr><tr><td><code>--disable-feature-dataset &lt;name&gt;</code></td><td></td><td></td><td>Skip loading an optional dataset to save memory. Options: <code>ROUTE_STEPS</code>, <code>ROUTE_GEOMETRY</code>.</td></tr></tbody></table><h3 id="query-limits" tabindex="-1">Query limits <a class="header-anchor" href="#query-limits" aria-label="Permalink to &quot;Query limits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>--max-viaroute-size &lt;n&gt;</code></td><td><code>500</code></td><td>Maximum number of waypoints in a route query.</td></tr><tr><td><code>--max-trip-size &lt;n&gt;</code></td><td><code>100</code></td><td>Maximum number of locations in a trip query.</td></tr><tr><td><code>--max-table-size &lt;n&gt;</code></td><td><code>100</code></td><td>Maximum number of locations in a table query.</td></tr><tr><td><code>--max-matching-size &lt;n&gt;</code></td><td><code>100</code></td><td>Maximum number of locations in a map-matching query.</td></tr><tr><td><code>--max-nearest-size &lt;n&gt;</code></td><td><code>100</code></td><td>Maximum number of results in a nearest query.</td></tr><tr><td><code>--max-alternatives &lt;n&gt;</code></td><td><code>3</code></td><td>Maximum number of alternative routes (MLD only).</td></tr><tr><td><code>--max-matching-radius &lt;m&gt;</code></td><td><code>-1</code> (unlimited)</td><td>Maximum search radius in metres for map-matching.</td></tr><tr><td><code>--default-radius &lt;m&gt;</code></td><td><code>-1</code> (unlimited)</td><td>Default snap radius for all queries.</td></tr><tr><td><code>--max-header-size &lt;bytes&gt;</code></td><td><code>0</code> (auto)</td><td>Maximum HTTP header size in bytes.</td></tr></tbody></table><hr><h2 id="osrm-datastore" tabindex="-1">osrm-datastore <a class="header-anchor" href="#osrm-datastore" aria-label="Permalink to &quot;osrm-datastore&quot;">​</a></h2><p>Loads a prepared dataset into shared memory so that one or more <code>osrm-routed</code> processes can serve it with zero-copy access. Enables live traffic updates without restarting the server.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>osrm-datastore [options] &lt;base.osrm&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Short</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>--dataset-name &lt;name&gt;</code></td><td></td><td></td><td>Name for this dataset in shared memory. Allows multiple datasets to coexist.</td></tr><tr><td><code>--max-wait &lt;s&gt;</code></td><td><code>-1</code> (unlimited)</td><td>Seconds to wait for a running update to finish before forcibly acquiring the lock.</td><td></td></tr><tr><td><code>--only-metric</code></td><td></td><td></td><td>Reload only the metric (weights/durations) without replacing the full dataset. Optimized for frequent traffic updates.</td></tr><tr><td><code>--disable-feature-dataset &lt;name&gt;</code></td><td></td><td></td><td>Skip loading an optional dataset. Options: <code>ROUTE_STEPS</code>, <code>ROUTE_GEOMETRY</code>.</td></tr><tr><td><code>--remove-locks</code></td><td><code>-r</code></td><td></td><td>Remove stale shared-memory locks and exit.</td></tr><tr><td><code>--spring-clean</code></td><td><code>-s</code></td><td></td><td>Remove all OSRM shared memory regions and exit.</td></tr><tr><td><code>--list</code></td><td></td><td></td><td>List all datasets currently loaded in shared memory.</td></tr><tr><td><code>--list-blocks</code></td><td></td><td></td><td>List all shared memory blocks currently in use.</td></tr></tbody></table>`,45)])])}const u=e(s,[["render",i]]);export{m as __pageData,u as default};
